-- Scriptorium — seed
--
-- Generated by pipeline/make_seed.py from list.csv and matches.csv.
-- Re-runnable: every statement is an upsert. Review before running.
--
-- Work ids are permanent. Notes anchor to them and they appear in URLs.

begin;

-- Lists ------------------------------------------------------------
on conflict (id) do update set name = excluded.name, description = excluded.description, examinable = excluded.examinable, sort = excluded.sort;

-- Sections ---------------------------------------------------------
on conflict (id) do update set letter = excluded.letter, title = excluded.title, kind = excluded.kind, sort = excluded.sort;

-- Works ------------------------------------------------------------
on conflict (id) do update set
  title = excluded.title,
  author = excluded.author,
  year = excluded.year,
  kind = excluded.kind,
  container_id = excluded.container_id,
  isbn = excluded.isbn,
  purpose = excluded.purpose,
  standing = excluded.standing,
  source_format = excluded.source_format,
  source_path = excluded.source_path,
  page_offset = excluded.page_offset,
  notes_internal = excluded.notes_internal,
  updated_at = now();

-- Placement --------------------------------------------------------
on conflict (list_id, work_id) do update set section_id = excluded.section_id, ordinal = excluded.ordinal;

commit;
